import{_ as h,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Đạo đức Công nghệ và Giới hạn An toàn","description":"","frontmatter":{},"headers":[],"relativePath":"vi/68-技术伦理与安全边界.md","filePath":"vi/68-技术伦理与安全边界.md","lastUpdated":1789183869000}'),g={name:"vi/68-技术伦理与安全边界.md"};function a(o,n,l,u,r,e){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="đao-đuc-cong-nghe-va-gioi-han-an-toan" tabindex="-1">Đạo đức Công nghệ và Giới hạn An toàn <a class="header-anchor" href="#đao-đuc-cong-nghe-va-gioi-han-an-toan" aria-label="Permalink to &quot;Đạo đức Công nghệ và Giới hạn An toàn&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>68</td></tr><tr><td>Mô-đun</td><td>Hệ thống Công nghệ và Năng lượng</td></tr><tr><td>Từ khóa cốt lõi</td><td>Đạo đức công nghệ, giới hạn an toàn, phân loại rủi ro, công nghệ cấm, xem xét đạo đức</td></tr></tbody></table><h2 id="_1-nguyen-tac-co-ban-cua-đao-đuc-cong-nghe" tabindex="-1">1. Nguyên tắc Cơ bản của Đạo đức Công nghệ <a class="header-anchor" href="#_1-nguyen-tac-co-ban-cua-đao-đuc-cong-nghe" aria-label="Permalink to &quot;1. Nguyên tắc Cơ bản của Đạo đức Công nghệ&quot;">​</a></h2><p>Đạo đức công nghệ của nền văn minh cộng sinh neo được xây dựng trên giá trị cơ bản &quot;tiến hóa cộng sinh&quot;. Nghiên cứu và áp dụng bất kỳ công nghệ nào cũng phải trả lời một câu hỏi cốt lõi: công nghệ này có thúc đẩy tiến hóa cộng sinh của tất cả các sinh vật, hay cung cấp phương tiện mới cho việc cướp bóc và gây hại? Nếu câu trả lời là cái sau, bất kể hiệu quả cá nhân của công nghệ đó lớn đến đâu, nó cũng phải bị hạn chế nghiêm ngặt hoặc cấm đoán.</p><p>Nguyên tắc cơ bản của đạo đức công nghệ bao gồm ba điều:</p><ul><li><strong>Nguyên tắc không gây hại</strong>: Việc áp dụng công nghệ không được gây ra những tổn thương không cần thiết cho bất kỳ sinh vật nào, không được cung cấp công cụ cho việc tu luyện săn mồi</li><li><strong>Nguyên tắc lợi ích cộng sinh</strong>: Sự phát triển của công nghệ nên nhắm đến việc nâng cao mức độ cộng sinh của toàn bộ nền văn minh, thay vì chỉ tăng cường khả năng của một vài cá nhân</li><li><strong>Nguyên tắc minh bạch và có thể truy vết</strong>: Quá trình nghiên cứu và hồ sơ áp dụng của tất cả các công nghệ cấp kỹ thuật luật phải có thể truy vết được, chấp nhận xem xét đạo đức và giám sát công chúng</li></ul><h2 id="_2-he-thong-phan-loai-rui-ro-cong-nghe" tabindex="-1">2. Hệ thống Phân loại Rủi ro Công nghệ <a class="header-anchor" href="#_2-he-thong-phan-loai-rui-ro-cong-nghe" aria-label="Permalink to &quot;2. Hệ thống Phân loại Rủi ro Công nghệ&quot;">​</a></h2><p>Nền văn minh cộng sinh đã thiết lập một hệ thống phân loại rủi ro công nghệ nghiêm ngặt, thực hiện đánh giá rủi ro và quản lý phân loại cho tất cả các công nghệ cấp kỹ thuật luật:</p><table tabindex="0"><thead><tr><th>Cấp độ Rủi ro</th><th>Tên</th><th>Đặc điểm</th><th>Yêu cầu Quản lý</th></tr></thead><tbody><tr><td>R0</td><td>Không có rủi ro</td><td>Công nghệ cấp khoa học và công nghệ thực tế, không liên quan đến thao tác luật</td><td>Quản lý thông thường, nghiên cứu và áp dụng tự do</td></tr><tr><td>R1</td><td>Rủi ro thấp</td><td>Công nghệ cấp trao quyền luật, cải thiện hiệu suất của công nghệ hiện có</td><td>Quản lý đăng ký, phải vượt qua kiểm tra an toàn cơ bản</td></tr><tr><td>R2</td><td>Rủi ro trung bình</td><td>Công nghệ cấp kỹ thuật luật, liên quan đến thao tác luật có giới hạn</td><td>Quản lý giấy phép, phải vượt qua xem xét đạo đức và xác minh không gian cách ly</td></tr><tr><td>R3</td><td>Rủi ro cao</td><td>Liên quan đến các thao tác có rủi ro cao như viết lại không gian, can thiệp ý thức, nhiệt hạch năng lượng, v.v.</td><td>Kiểm soát nghiêm ngặt, chỉ các tổ chức được ủy quyền mới có thể nghiên cứu trong không gian cách ly cấp S</td></tr><tr><td>R4</td><td>Cấp độ cấm</td><td>Các công nghệ có thể gây ra sự sụp đổ mặt phẳng, tuyệt chủng ý thức, ô nhiễm luật</td><td>Cấm hoàn toàn nghiên cứu và áp dụng, kiến thức liên quan được liệt kê là cấm</td></tr></tbody></table><p>Cấp độ rủi ro không phải là bất biến. Cùng với sự trưởng thành của công nghệ và sự hoàn thiện của các biện pháp an toàn, một số công nghệ cấp R3 có thể được hạ xuống cấp R2; ngược lại, nếu phát hiện các nguy cơ an toàn mới, công nghệ cũng có thể bị kiểm soát chặt chẽ hơn.</p><h2 id="_3-gioi-han-an-toan-chinh" tabindex="-1">3. Giới hạn An toàn Chính <a class="header-anchor" href="#_3-gioi-han-an-toan-chinh" aria-label="Permalink to &quot;3. Giới hạn An toàn Chính&quot;">​</a></h2><p>Đạo đức công nghệ và giới hạn an toàn đã rõ ràng xác định các đường đỏ sau đây không thể vượt qua:</p><h3 id="_3-1-gioi-han-an-toan-nang-luong" tabindex="-1">3.1 Giới hạn An toàn Năng lượng <a class="header-anchor" href="#_3-1-gioi-han-an-toan-nang-luong" aria-label="Permalink to &quot;3.1 Giới hạn An toàn Năng lượng&quot;">​</a></h3><ul><li>Cấm thực hiện các thí nghiệm giải phóng năng lượng vượt quá khả năng chịu đựng của mặt phẳng tại mặt phẳng chính</li><li>Cấm nghiên cứu các công nghệ trích xuất năng lượng với mục đích cướp bóc năng lượng của các sinh vật khác</li><li>Nghiên cứu năng lượng kỳ lạ phải được thực hiện trong không gian cách ly và tuân thủ nghiêm ngặt ba loại quy trình xử lý</li></ul><h3 id="_3-2-gioi-han-an-toan-khong-gian" tabindex="-1">3.2 Giới hạn An toàn Không gian <a class="header-anchor" href="#_3-2-gioi-han-an-toan-khong-gian" aria-label="Permalink to &quot;3.2 Giới hạn An toàn Không gian&quot;">​</a></h3><ul><li>Cấm thực hiện các thí nghiệm viết lại luật không gian trong trạng thái không cách ly</li><li>Việc mở kênh giữa các mặt phẳng phải thông qua đánh giá an toàn để ngăn ngừa tổn thương vĩnh viễn cho rào cản giữa các mặt phẳng</li><li>Việc xây dựng và phá hủy không gian cách ly phải tuân theo giao thức tiêu chuẩn, không được để lại dấu vết không gian</li></ul><h3 id="_3-3-gioi-han-an-toan-y-thuc" tabindex="-1">3.3 Giới hạn An toàn Ý thức <a class="header-anchor" href="#_3-3-gioi-han-an-toan-y-thuc" aria-label="Permalink to &quot;3.3 Giới hạn An toàn Ý thức&quot;">​</a></h3><ul><li>Cấm nghiên cứu các công nghệ thao tác ý thức, thay đổi trí nhớ không có sự đồng ý</li><li>Nghiên cứu cơ thể thay thế tối phải tuân theo các nguyên tắc đạo đức linh hồn kép và bốn quy tắc xử lý nhánh</li><li>Công nghệ giao diện miền ý thức phải có cơ cấu cầu chì an toàn không thể đảo ngược</li></ul><h3 id="_3-4-gioi-han-an-toan-thoi-gian" tabindex="-1">3.4 Giới hạn An toàn Thời gian <a class="header-anchor" href="#_3-4-gioi-han-an-toan-thoi-gian" aria-label="Permalink to &quot;3.4 Giới hạn An toàn Thời gian&quot;">​</a></h3><ul><li>Các thao tác quay ngược thời gian phải tuân thủ nghiêm ngặt nguyên tắc &quot;quan sát trước, can thiệp có giới hạn sau&quot;</li><li>Cấm bất kỳ thí nghiệm và thao tác nào có thể gây ra nghịch lý thời gian</li><li>Hồ sơ quay ngược thời gian phải liên tục được giám sát bởi cơ cấu phòng ngừa nghịch lý thời gian</li></ul><h2 id="_4-co-cau-xem-xet-đao-đuc" tabindex="-1">4. Cơ cấu Xem xét Đạo đức <a class="header-anchor" href="#_4-co-cau-xem-xet-đao-đuc" aria-label="Permalink to &quot;4. Cơ cấu Xem xét Đạo đức&quot;">​</a></h2><p>Để đảm bảo việc thực hiện đạo đức công nghệ, nền văn minh cộng sinh đã thiết lập một cơ cấu xem xét đạo đức đa cấp độ:</p><ol><li><strong>Xem xét trước nghiên cứu</strong>: Tất cả các dự án nghiên cứu công nghệ cấp R2 trở lên phải nộp đơn xin xem xét đạo đức trước khi bắt đầu, và một ủy ban đạo đức công nghệ độc lập sẽ đánh giá rủi ro và lợi ích của chúng</li><li><strong>Giám sát trong quá trình thí nghiệm</strong>: Quá trình thí nghiệm của công nghệ cấp R3 phải có người quan sát đạo đức có mặt suốt thời gian, và dữ liệu thí nghiệm phải được tải lên thời gian thực cho hệ thống giám sát đạo đức của mạng lưới neo</li><li><strong>Đánh giá trước áp dụng</strong>: Trước khi công nghệ mới đi từ phòng thí nghiệm đến sản xuất hàng loạt, nó phải thông qua đánh giá an toàn độc lập và đánh giá tác động xã hội</li><li><strong>Theo dõi sau áp dụng</strong>: Các công nghệ đã được áp dụng tiếp tục nhận được theo dõi an toàn, và khi phát hiện các vấn đề đạo đức mới, có thể bắt đầu đánh giá lại hoặc thậm chí chương trình thu hồi bất cứ lúc nào</li><li><strong>Tham gia công chúng</strong>: Các quyết định công nghệ quan trọng phải thông qua quy trình điều trần công chúng, đảm bảo rằng hướng phát triển công nghệ phù hợp với lợi ích chung của toàn bộ nền văn minh</li></ol><h2 id="_5-danh-sach-cong-nghe-cam" tabindex="-1">5. Danh sách Công nghệ Cấm <a class="header-anchor" href="#_5-danh-sach-cong-nghe-cam" aria-label="Permalink to &quot;5. Danh sách Công nghệ Cấm&quot;">​</a></h2><p>Các công nghệ sau đây được liệt kê rõ ràng là công nghệ cấm cấp R4, với việc cấm hoàn toàn nghiên cứu:</p><ul><li>Vũ khí cấp độ phá hủy mặt phẳng: công nghệ vũ khí có khả năng phá hủy cấu trúc không gian của toàn bộ mặt phẳng</li><li>Thiết bị tuyệt chủng ý thức: công nghệ có khả năng xóa hàng loạt hoặc nô lệ hóa ý thức của các sinh vật</li><li>Động cơ luật cướp bóc: công nghệ sử dụng việc cướp bóc có hệ thống nguồn gốc của các sinh vật khác làm cơ cấu vận hành</li><li>Máy phát nghịch lý thời gian: công nghệ cố tình tạo ra nghịch lý thời gian để thu lợi bất chính</li><li>Thiết bị phát tán ô nhiễm luật: công nghệ cố ý lan tỏa ô nhiễm luật để phá hủy các nền văn minh khác</li></ul><p>Kiến thức liên quan đến các công nghệ cấm được lưu trữ mã hóa trong kho lưu trữ cấm của neo chính, và chỉ có thể được xem xét trong các cuộc khủng hoảng an toàn cấp văn minh, sau khi được ủy quyền bởi thẩm quyền cao nhất của cơ quan quản lý cộng sinh.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Đạo đức công nghệ và giới hạn an toàn là &quot;hệ thống phanh&quot; của hệ thống công nghệ nền văn minh cộng sinh neo. Nó đảm bảo rằng sự phát triển của công nghệ luôn phục vụ mục tiêu cơ bản của tiến hóa cộng sinh, mà không bị dị hóa thành công cụ cướp bóc mới. Trong một thời đại mà luật có thể được thao tác thông qua kỹ thuật, giới hạn đạo đức quan trọng hơn khả năng công nghệ — chỉ bằng cách giữ vững giới hạn, công nghệ mới thực sự có thể trở thành trợ lực, chứ không phải mối đe dọa, cho sự tiến bộ chung của tất cả các chủng tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>60-Tổng quan Hệ thống Công nghệ</li><li>19-Đạo đức và Giới hạn Tu luyện</li><li>88-Nguyên tắc Đạo đức Giữa các Mặt phẳng</li></ul>',31)])])}const m=h(g,[["render",a]]);export{p as __pageData,m as default};
